// n = total distinct types INCLUDING sphinx, as currently counted
const current = n => n <= 3 ? 2 : 2*(n-3) - 1;

// hypothesis: score the OTHER types (excluding the sphinx itself):
// 1 point per other-type for the first 2 others, 2 points per other-type beyond that
const others = o => Math.min(o,2)*1 + Math.max(o-2,0)*2;
const hyp = n => others(n-1);

for (const n of [1,2,3,4,5,6,7,8]) {
  console.log(`n=${n}  current=${current(n)}  hypothesis=${hyp(n)}  ${current(n)===hyp(n)?'':'  <-- MISMATCH'}`);
}
EOF
node /tmp/probe.mjs

