// The examples pin down only four points on this curve:
//   2 types -> 2, 3 types -> 2, 5 types -> 3, 6 types -> 5.
// Up to three types the score is flat at 2. From five types on, each further
// type is worth 2 more, so that band is a line of slope 2 through (5, 3).
//
// NOTE: those two bands do not meet. Extrapolating the slope-2 line back to
// four types yields 1, i.e. a fourth monster type LOWERS the Sphinx score from
// 2 to 1. No example covers four types, so this is unverified and preserved
// here only to keep behaviour unchanged. See the note in the summary.
const FLAT_BAND_TYPE_LIMIT = 3;
const FLAT_BAND_SCORE = 2;
const POINTS_PER_ADDITIONAL_TYPE = 2;

const scoreForTypeCount = (distinctTypeCount: number): number => {
  if (distinctTypeCount <= FLAT_BAND_TYPE_LIMIT) return FLAT_BAND_SCORE;
  const typesBeyondFive = distinctTypeCount - 5;
  return 3 + POINTS_PER_ADDITIONAL_TYPE * typesBeyondFive;
};

